    /**
     * Tests getting all TimeEntrys.
     *
     * @return    Collection
     */
    public List<TimeEntry> testGetAll() throws Throwable {
    LOGGER.info( "TimeEntryTest:testGetAll() - Retrieving Collection of TimeEntrys:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all TimeEntry : " );
    List<TimeEntry> collection  = null;

    try {
        // call the static get method on the TimeEntryService
        collection = service.getAllTimeEntry();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            TimeEntry currEntity  = null;
            Iterator<TimeEntry> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getTimeEntryId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

